package com.codespace.ide.chat.capabilities

import android.content.Context
import org.json.JSONArray
import org.json.JSONObject

import java.io.InputStream

/**
 * G-E-a BUNDLED CAPABILITY TABLE — source 3 of the resolution chain.
 *
 * Parses the committed asset `capability-table.json`, generated by the
 * committed script tools/gen_capability_table.py from BerriAI/LiteLLM's
 * model_prices_and_context_window.json (MIT). The header records source,
 * date, and license; [tableDate] surfaces the date (unit-tested; the UI line
 * ships with the G-E-b picker line).
 *
 * BOUNDED PARSING throughout (advisor conditions c + d): row caps, string
 * caps, sane numeric caps, unknown fields IGNORED, any poison -> empty table
 * that contributes nothing (never a crash, never a guess).
 */
object ModelCapabilityTable {

    internal const val ASSET_NAME = "capability-table.json"
    internal const val MAX_ROWS = 1_000
    internal const val MAX_MATCH_LEN = 64
    internal const val MAX_CONTEXT = 100_000_000L

    @Volatile private var initialized = false
    @Volatile private var rowsByProvider: Map<String, List<BundledRow>> = emptyMap()
    @Volatile private var date: String? = null

    /** Parsed bundled row (bounded fields only). */
    internal data class BundledRow(
        val provider: String,
        val match: String,
        val images: Boolean?,
        val tools: Boolean?,
        val pdf: Boolean?,
        val streaming: Boolean?,
        val maxContextTokens: Long?,
    )

    fun init(ctx: Context) {
        if (initialized) return
        synchronized(this) {
            if (initialized) return
            try {
                ctx.assets.open(ASSET_NAME).use { stream -> load(stream) }
            } catch (_: Exception) {
                // Missing/unreadable asset -> empty table (source contributes
                // nothing); never crash the app over an optional table.
                rowsByProvider = emptyMap()
                date = null
            }
            initialized = true
        }
    }

    /** Test seam: load from any stream. Bounded, poison-safe. */
    internal fun load(stream: InputStream) {
        try {
            val text = stream.readBytes().toString(Charsets.UTF_8)
            loadFromString(text)
        } catch (_: Exception) {
            rowsByProvider = emptyMap()
            date = null
        }
    }

    internal fun loadFromString(text: String) {
        val root = JSONObject(text)
        date = root.optString("generated").take(32).ifBlank { null }
        val providers = root.optJSONObject("providers") ?: JSONObject()
        val out = LinkedHashMap<String, MutableList<BundledRow>>()
        var total = 0
        for (providerId in providers.keys()) {
            val arr: JSONArray = providers.optJSONArray(providerId) ?: continue
            val bucket = out.getOrPut(providerId.take(MAX_MATCH_LEN)) { mutableListOf() }
            for (i in 0 until arr.length()) {
                if (total >= MAX_ROWS) return finalize(out)
                val o = arr.optJSONObject(i) ?: continue
                val match = o.optString("match").take(MAX_MATCH_LEN)
                if (match.isBlank()) continue
                bucket.add(BundledRow(
                    provider = providerId.take(MAX_MATCH_LEN),
                    match = match,
                    images = o.optBooleanOrAbsent("images"),
                    tools = o.optBooleanOrAbsent("tools"),
                    pdf = o.optBooleanOrAbsent("pdf"),
                    streaming = o.optBooleanOrAbsent("streaming"),
                    maxContextTokens = o.optSaneLong("maxContext"),
                ))
                total++
            }
        }
        finalize(out)
    }

    private fun finalize(out: Map<String, MutableList<BundledRow>>) {
        rowsByProvider = out
    }

    /** The table's generation date (from the header) — shown in the UI. */
    fun tableDate(): String? = date

    /**
     * Longest-prefix match wins (a "claude-sonnet-4" row covers
     * "claude-sonnet-4-5-20260101"). No row -> null flags: UNKNOWN.
     */
    fun bundledFlagsFor(providerId: String?, modelId: String?): ModelCapabilityFlags? {
        if (providerId == null || modelId == null) return null
        val rows = rowsByProvider[providerId] ?: return null
        var best: BundledRow? = null
        for (r in rows) {
            if (!modelId.startsWith(r.match)) continue
            if (best == null || r.match.length > best.match.length) best = r
        }
        return best?.let {
            ModelCapabilityFlags(
                acceptsImages = it.images,
                acceptsPdf = it.pdf,
                supportsTools = it.tools,
                supportsStreaming = it.streaming,
                maxContextTokens = it.maxContextTokens,
                // audio/video are NOT in the bundled table (LiteLLM has no
                // per-model audio-input flag) — stay UNKNOWN, U5's live
                // source and user toggles fill them.
            )
        }
    }

    // ── Bounded field helpers (optBoolean with explicit absent = null) ──

    private fun JSONObject.optBooleanOrAbsent(key: String): Boolean? =
        if (has(key)) try { getBoolean(key) } catch (_: Exception) { null } else null

    private fun JSONObject.optSaneLong(key: String): Long? = try {
        if (!has(key)) null else getLong(key).coerceIn(1L, MAX_CONTEXT)
    } catch (_: Exception) { null }

    /** Test hook: reset to uninitialized. */
    internal fun resetForTest() {
        initialized = false
        rowsByProvider = emptyMap()
        date = null
    }

    /** Test hook: feed text directly (assets are unavailable under JVM stubs). */
    internal fun loadForTest(text: String) {
        resetForTest()
        try {
            loadFromString(text)
        } catch (_: Exception) {
            rowsByProvider = emptyMap()
            date = null
        }
        initialized = true
    }
}
